// Shape the dossier into flat CRM-ready fields plus a Slack message.
const d = items[0]?.json || {};
if (!d.domain) {
  throw new Error('The Actor returned no dossier. Check that the request body contains a valid "domain".');
}

const crm = {
  domain: d.domain,
  company: d.company,
  websiteTitle: d.websiteTitle || '',
  emailProvider: d.emailProvider || '',
  techStack: (d.detectedTechStack || []).join(', '),
  hasSpfRecord: d.hasSpfRecord,
  registeredAt: d.registeredAt || '',
  activeSubdomains: (d.activeSubdomains || []).join(', '),
  socialMentionsCount: d.socialMentionsCount || 0,
  localLeadsCount: d.localLeadsCount || 0,
  scrapedAt: d.scrapedAt
};

const slackText = [
  `*New account dossier: ${crm.domain}*`,
  `Website: ${crm.websiteTitle || 'n/a'}`,
  `Email provider: ${crm.emailProvider || 'n/a'}`,
  `Tech stack: ${crm.techStack || 'none detected'}`,
  `Registered: ${crm.registeredAt || 'unknown'}`,
  `HN/Reddit mentions: ${crm.socialMentionsCount}`
].join('\n');

return [{ json: { crm, slackText, llmMarkdown: d.llmMarkdown || '' } }];
